const santana=()=>`<g data-fine="1"><path d="M-3,10 L6.5,-11 L16,10Z" fill="#C9A15A"/><path d="M0.6,6 L6.5,-7 M12.4,6 L6.5,-7 M2.6,1.6 L10.4,1.6 M4.4,-2.6 L8.6,-2.6" stroke="#9E7A3A" stroke-width=".55" fill="none"/><path d="M1.6,10 L6.5,-1.4 L11.4,10Z" fill="${C.white}"/><path d="M1.6,10 L6.5,-1.4 L11.4,10" stroke="#B4533A" stroke-width=".8" fill="none"/><rect x="5.3" y="5.4" width="2.4" height="4.6" fill="#B4533A"/><rect x="3" y="6.2" width="1.4" height="1.4" fill="#2E7D9A"/><rect x="8.6" y="6.2" width="1.4" height="1.4" fill="#2E7D9A"/><path d="M-3,10 L6.5,-11 L16,10" stroke="#FFFDF8" stroke-opacity=".6" stroke-width=".5" fill="none"/></g>`;
