  return `<g data-thin="1" transform="translate(${x},${y}) scale(${flip?-s:s},${s})">`
   +`<path d="M-13,-7 C-22,-10 -25,-20 -21,-27 C-19,-30 -16,-29 -17,-26 C-20,-20 -18,-13 -11,-9" fill="${FUR}"/>`
   +`<path data-fine="1" d="M-21,-15 l2.6,-1 M-21.6,-20 l2.6,0 M-20.2,-24.6 l2.2,1" stroke="${DARK}" stroke-width="1.2"/>`
   +leg('M10,-2 L13,13',DARK)+leg('M-10,0 L-7,13',DARK)
   +`<path d="M-15,-4 Q-15,-11 -6,-11.4 Q4,-12.4 10,-10.4 Q15,-8.6 15.4,-3.6 Q12,1.6 4,1.6 Q-6,2.6 -12,2 Q-16,1 -15,-4Z" fill="${FUR}"/>`
   +`<path d="M2,1 Q8,2 13,-1 Q10,-3 4,-2Z" fill="${PALE}"/>`
   +`<path data-fine="1" d="M-8,-11 Q-7,-7 -9,-3 M-3,-11.8 Q-2,-7 -4,-2 M2,-12 Q3,-7 1,-2.4 M7,-11.4 Q8,-7 6.4,-3" stroke="${DARK}" stroke-width="1.3" fill="none"/>`
   +leg('M12.6,-1 Q11.6,6 8.6,13',FUR)+leg('M-9,1 Q-13,7 -15.4,13',FUR)
   +`<ellipse cx="8.8" cy="13.4" rx="1.8" ry="1" fill="${FUR}"/><ellipse cx="-15.8" cy="13.4" rx="1.8" ry="1" fill="${FUR}"/>`
   +`<path data-fine="1" d="M10.6,6 l2.4,-.4 M-12,6.6 l2.4,.2" stroke="${DARK}" stroke-width="1"/>`
   +`<path d="M12,-9 Q15,-12 18,-12.6 L19,-8 Q16,-5 13,-5Z" fill="${FUR}"/>`
   +`<ellipse cx="18.4" cy="-11.2" rx="5" ry="4.2" fill="${FUR}"/>`
   +`<path d="M14.4,-14 L14.6,-20.4 L17.6,-15Z M18.6,-15.2 L21,-20.6 L22,-14Z" fill="${FUR}"/><path data-fine="1" d="M15.2,-15.2 L15.4,-18.6 L16.8,-15.4Z" fill="${NOSE}"/>`
