// ---------- Backdrops: colour washes, blurred depth, movement ----------
// Everything here sits in a data-bg group, so the stencil pass leaves it soft and out of focus.
let bgN=0;
function ridge(y,amp,n,ph){n=n*2;const st=400/n;let d=`M-20,${y}`;for(let i=0;i<n;i++){const x1=i*st+st*.5,x2=(i+1)*st+2;const w=.55+.3*Math.sin(i*1.9+ph)+.18*Math.sin(i*4.3+ph*2.1);const peak=y-amp*w;const tail=y-amp*(.3+.22*Math.cos(i*2.7+ph)+.12*Math.sin(i*5.1+ph));d+=` Q${x1.toFixed(0)},${(peak-amp*.25).toFixed(0)} ${x2.toFixed(0)},${tail.toFixed(0)}`}return d+' V270 H-20Z'}
function bd(top,bot,body){const id='bg'+(++bgN);
  return `<g data-bg="1" class="lay-far"><defs><linearGradient id="w${id}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${top}"/><stop offset="1" stop-color="${bot}"/></linearGradient>
  <filter id="far${id}" x="-15%" y="-15%" width="130%" height="130%"><feTurbulence type="fractalNoise" baseFrequency="0.018 0.03" numOctaves="3" seed="${bgN}" result="t"/><feDisplacementMap in="SourceGraphic" in2="t" scale="18" xChannelSelector="R" yChannelSelector="G" result="d"/><feGaussianBlur in="d" stdDeviation="6"/></filter><filter id="mid${id}" x="-15%" y="-15%" width="130%" height="130%"><feTurbulence type="fractalNoise" baseFrequency="0.03 0.05" numOctaves="3" seed="${bgN+7}" result="t"/><feDisplacementMap in="SourceGraphic" in2="t" scale="10" xChannelSelector="R" yChannelSelector="G" result="d"/><feGaussianBlur in="d" stdDeviation="3"/></filter></defs>
  <rect x="-5" y="-5" width="410" height="270" fill="url(#w${id})"/>${body(`url(#far${id})`,`url(#mid${id})`)}</g>`}
const farMts=(f,y,col,op=.5,ph=.4)=>`<path d="${ridge(y,46,6,ph)}" fill="${col}" opacity="${op}" filter="${f}"/>`;
const terraces=(m,y,col,ph=1)=>`<path d="${ridge(y,26,5,ph)}" fill="${col}" opacity=".55" filter="${m}"/>`+R(6,i=>`<path d="M-10,${y+8+i*10} C90,${y-2+i*10} 170,${y+16+i*10} 260,${y+4+i*10} S360,${y-4+i*10} 410,${y+6+i*10}" stroke="#3E6B3A" stroke-opacity=".28" stroke-width="1.2" fill="none" filter="${m}"/>`);
const road=(m,d,w=7)=>`<path d="${d}" stroke="#8C8478" stroke-opacity=".45" stroke-width="${w}" fill="none" stroke-linecap="round" filter="${m}"/><path d="${d}" stroke="#FFFDF8" stroke-opacity=".5" stroke-width="1" stroke-dasharray="4 5" fill="none" filter="${m}"/>`;
const clouds=(f,list)=>list.map(([x,y,r],j)=>`<g opacity=".8" filter="${f}">`+R(4,i=>`<ellipse cx="${(x+(i-1.5)*r*.45+(j%2?4:-3)).toFixed(0)}" cy="${(y+((i*7+j*3)%5-2)*r*.06).toFixed(1)}" rx="${(r*(.42+((i+j)%3)*.12)).toFixed(0)}" ry="${(r*(.22+((i*2+j)%3)*.06)).toFixed(1)}" fill="#FFFFFF"/>`)+`</g>`).join('');
const wind=(list,op=.75)=>list.map(([y,a])=>`<path d="M-10,${y} C80,${y-a} 150,${y+a*.8} 230,${y-a*.3} S350,${y-a} 410,${y-a*.2}" stroke="#FFFFFF" stroke-opacity="${op}" stroke-width="1.5" fill="none" stroke-linecap="round"/>`).join('');
const beam=(f,pts)=>`<polygon points="${pts}" fill="#FFF3D6" opacity=".55" filter="${f}"/>`;
const lights=(list)=>list.map(([x,y])=>`<circle cx="${x}" cy="${y}" r="1.7" fill="#F7D774" opacity="1"/>`).join('');
const palms=(m,xs,y)=>xs.map(x=>`<path d="M${x},${y} Q${x+4},${y-30} ${x-2},${y-58}" stroke="#4E6B45" stroke-opacity=".5" stroke-width="3" fill="none" filter="${m}"/>`+R(5,i=>`<path d="M${x-2},${y-58} Q${x-2+Math.cos(i*1.25+.3)*16},${y-70+Math.sin(i*1.25)*4} ${x-2+Math.cos(i*1.25+.3)*26},${y-52+Math.sin(i*1.25+.3)*8}" stroke="#4E6B45" stroke-opacity=".5" stroke-width="3" fill="none" filter="${m}"/>`)).join('');
const arches=(f,y)=>R(6,i=>`<path d="M${i*70-10},${y} V${y-40} A30,30 0 0 1 ${i*70+50},${y-40} V${y}" fill="#86AEDB" opacity=".35" filter="${f}"/>`)+`<rect x="-5" y="${y}" width="410" height="8" fill="#173F5F" opacity=".25" filter="${f}"/>`;
const crowd=(f,y)=>R(8,i=>`<ellipse cx="${20+i*52}" cy="${y-22-(i%3)*4}" rx="7" ry="8" fill="#6B635C" opacity=".35" filter="${f}"/><path d="M${8+i*52},${y} Q${20+i*52},${y-36-(i%3)*4} ${32+i*52},${y}Z" fill="${i%2?'#B4533A':'#2E7D9A'}" opacity=".3" filter="${f}"/>`);
function curtains(x,y,w,h,out=false){const s=out?-1:1;
  return `<g data-bg="1"><path d="M${x+2},${y-4} C${x+26*s},${y+24} ${x-4*s},${y+56} ${x+22*s},${y+h-6} Q${x+8*s},${y+h+10} ${x-10*s},${y+h+6} C${x-14*s},${y+60} ${x+6*s},${y+30} ${x-8*s},${y-4}Z" fill="#FFFFFF" opacity=".72"/>
  <path d="M${x+w-2},${y-4} C${x+w-24*s},${y+30} ${x+w+6*s},${y+64} ${x+w-18*s},${y+h-4} Q${x+w-4*s},${y+h+10} ${x+w+12*s},${y+h+6} C${x+w+14*s},${y+60} ${x+w-4*s},${y+28} ${x+w+8*s},${y-4}Z" fill="#FFFFFF" opacity=".72"/>
  <path d="M${x+4},${y+10} C${x+18*s},${y+40} ${x},${y+70} ${x+14*s},${y+h-8} M${x+w-4},${y+10} C${x+w-18*s},${y+44} ${x+w},${y+74} ${x+w-12*s},${y+h-8}" stroke="#D8D9D4" stroke-width="1" fill="none"/></g>`}
