  hill:()=>bd('#8FB8E0','#F4EBDD',(f,m)=>clouds(f,[[60,30,46],[220,20,60],[360,48,34]])+farMts(f,96,'#5C7F96',.6,1.1)+terraces(m,118,'#8BA65B',.4)+road(m,'M400,96 C360,90 330,104 290,96 S220,80 180,90',4)+wind([[40,10],[58,7]])),
