const leaf=(x,y,r,len,col)=>`<path transform="translate(${x},${y}) rotate(${r})" d="M0,0 Q${len*.5},-${len*.22} ${len},0 Q${len*.5},${len*.22} 0,0Z" fill="${col}"/>`;
const bougain=(x,y,flip=1)=>nearG(R(7,i=>leaf(x,y,(i*26-40)*flip+(flip<0?180:0),70+i*6,i%2?'#2F5D3A':'#4E7B45'))+R(16,i=>{const a=i*0.9,r=22+(i%4)*12;const cx=x+Math.cos(a)*r*flip,cy=y+Math.sin(a)*r*.7+10;return `<g transform="translate(${cx.toFixed(0)},${cy.toFixed(0)}) rotate(${i*40})"><path d="M0,0 Q-9,-12 0,-16 Q9,-12 0,0Z M0,0 Q12,-4 14,6 Q4,8 0,0Z M0,0 Q-12,-4 -14,6 Q-4,8 0,0Z" fill="${i%3?'#A3478F':'#8C6BB8'}"/></g>`}));
const strelitzia=(x,y,flip=1)=>nearG(R(5,i=>leaf(x,y,(-70-i*18)*flip+(flip<0?180:0),110+i*10,i%2?'#2F5D3A':'#5C8A5A'))+`<g transform="translate(${x+40*flip},${y-70}) scale(${flip},1)"><path d="M0,0 L60,-10 L10,10Z" fill="#2E7D9A"/><path d="M8,-2 L30,-48 L22,-4Z M16,-4 L46,-40 L30,-6Z M24,-6 L58,-30 L38,-8Z" fill="#EE8A2C"/><path d="M0,0 L-6,60" stroke="#2F5D3A" stroke-width="6"/></g>`);
const frond=(x,y,flip=1)=>nearG(`<path d="M${x},${y} Q${x+90*flip},${y+30} ${x+170*flip},${y+90}" stroke="#3E6B3A" stroke-width="4" fill="none"/>`+R(14,i=>{const t=i/14,px=x+170*flip*t,py=y+90*t*t+30*t*(1-t);return leaf(px,py,(70+i*2)*flip+(flip<0?180:0),48-i*1.6,i%2?'#3E6B3A':'#5C8A5A')+leaf(px,py,(-20+i*3)*flip+(flip<0?180:0),40-i*1.4,'#4E7B45')}));
const basket=(x,y)=>nearG(`<path d="M${x},-10 L${x},${y-20}" stroke="#6B635C" stroke-width="2"/><path d="M${x-40},${y} Q${x},${y+34} ${x+40},${y}Z" fill="#946640"/>`+R(10,i=>`<circle cx="${x-36+i*8}" cy="${y-6-(i%3)*8}" r="9" fill="${['#EE8A2C','#8C6BB8','#B4533A','#EFC94A'][i%4]}"/>`)+R(5,i=>leaf(x-30+i*14,y+4,90+i*8,40,'#4E7B45')));
