  const town=items.sort((p,q)=>p[0]-q[0]).map(p=>p[1]).join('');
  // ---------- harbour and cruise ship ----------
  const ship=`<path d="M184,98 L316,98 L310,108 L192,108Z" fill="#1F3550"/><path d="M186,101 H314" stroke="#B4533A" stroke-width="1.2"/><rect x="196" y="86" width="108" height="12" fill="#FBF8F1"/><rect x="204" y="78" width="88" height="8" fill="#FBF8F1"/><rect x="214" y="72" width="64" height="6" fill="#FBF8F1"/>`
    +R(3,d=>R(26-d*7,i=>`<rect x="${198+d*8+i*4}" y="${89-d*8+(d===2?2:0)}" width="2" height="2" fill="#6E8FA8"/>`))+`<path d="M262,72 L264,62 L276,62 L278,72Z" fill="#FBF8F1"/><rect x="263" y="62" width="14" height="3" fill="#B4533A"/>`;
  const harbour=`<path d="M118,112 L196,108 L238,104 L318,104 L318,108 L242,108 L200,111.6 L118,115Z" fill="#B9B2A6"/><g transform="translate(262,104) scale(.5) translate(-250,-108)">${ship}</g>`;
