  maracujaCut:(x,y,r=3.4)=>`<circle data-flat="1" cx="${x}" cy="${y}" r="${r}" fill="#5E2F5A"/><circle data-flat="1" cx="${x}" cy="${y}" r="${r*.8}" fill="#F4ECD8"/><circle data-flat="1" cx="${x}" cy="${y}" r="${r*.66}" fill="#F0B42A"/>`+[[-.3,-.25],[.25,-.3],[.05,.05],[-.32,.22],[.3,.25],[0,-.48],[0,.45]].map(([a,b])=>`<circle data-flat="1" cx="${(x+a*r).toFixed(2)}" cy="${(y+b*r).toFixed(2)}" r="${(r*.11).toFixed(2)}" fill="#2A2018"/>`).join(''),
