// ---------- Stencil & airbrush treatment applied to every scene ----------
const NS='http://www.w3.org/2000/svg',PAPER='#FFFDF8';
const hx=h=>{const n=parseInt(h.slice(1),16);return[n>>16,(n>>8)&255,n&255]};
const toHex=a=>'#'+a.map(v=>Math.max(0,Math.min(255,Math.round(v))).toString(16).padStart(2,'0')).join('');
const mix=(h,t,k)=>{const A=hx(h),B=hx(t);return toHex(A.map((v,i)=>v+(B[i]-v)*k))};
const lum=h=>{const [r,g,b]=hx(h);return .299*r+.587*g+.114*b};
const okHex=h=>/^#[0-9a-f]{6}$/i.test(h||'');
