// point the camera: crop the viewBox, and keep the near layer pinned to the frame edges
function autoCam(svg){
  const R0=svg.getBoundingClientRect();if(!R0.width)return null;const k=400/R0.width;
  let x0=1e9,y0=1e9,x1=-1e9,y1=-1e9,n=0;
  svg.querySelectorAll('.o').forEach(e=>{const r=e.getBoundingClientRect();if(!r.width||!r.height)return;
    const bx=(r.left-R0.left)*k,by=(r.top-R0.top)*k,bw=r.width*k,bh=r.height*k;
    if(bw*bh>400*260*.45)return;
    const cx0=Math.max(0,bx),cy0=Math.max(0,by),cx1=Math.min(400,bx+bw),cy1=Math.min(260,by+bh);if(cx1<=cx0||cy1<=cy0)return;
    x0=Math.min(x0,cx0);y0=Math.min(y0,cy0);x1=Math.max(x1,cx1);y1=Math.max(y1,cy1);n++});
  if(!n)return null;
  const pad=14;x0-=pad;y0-=pad;x1+=pad;y1+=pad*.6;
  let w=Math.max(x1-x0,(y1-y0)/0.65,230);w=Math.min(w,400);const h=w*.65;
  let x=(x0+x1)/2-w/2,y=(y0+y1)/2-h/2;x=Math.max(0,Math.min(400-w,x));y=Math.max(0,Math.min(260-h,y));
  return [x,y,w]}
function frame(svg,cam){if(cam==='auto')cam=autoCam(svg);if(!cam)return svg;const [x,y,w]=cam,h=w*0.65;svg.setAttribute('viewBox',`${x} ${y} ${w} ${h}`);
  const n=svg.querySelector('.plane-near');if(n){const g=document.createElementNS(NS,'g');g.setAttribute('transform',`translate(${x},${y}) scale(${(w/400).toFixed(4)})`);while(n.firstChild)g.appendChild(n.firstChild);n.appendChild(g)}
  return svg}

