  const sc=e.target.closest('[data-sk]');if(sc){if(Date.now()-lpAt<700)return;document.querySelectorAll('.wcard.playing').forEach(x=>x.classList.remove('playing'));sc.classList.add('playing');clipPlay(si,+sc.dataset.sp,sc.dataset.sk);return}
  const qa=e.target.closest('[data-qa]');if(qa){answer(qa.dataset.qa);return}
  if(e.target.closest('#qnext')){quiz.i++;quiz.ans=null;drawQuiz();return}
  if(e.target.closest('#qagain')){newQuiz();drawQuiz();return}
  const w=e.target.closest('.w');if(w){if(Date.now()-lpAt<700)return;light(w.dataset.k);narrWord(w);return}
  const s=e.target.closest('[data-say]');if(s){light(s.dataset.say);const tw=$('text').querySelector(`.w[data-k="${s.dataset.say}"]`);if(tw)narrWord(tw);else{const f=first[s.dataset.say];if(f)clipPlay(f.s,f.p,s.dataset.say)}return}
  const c=e.target.closest('[data-ck]');if(c){const k=c.dataset.ck;known.has(k)?known.delete(k):known.add(k);save();renderPage();return}
  const g=e.target.closest('[data-go]');if(g){const [a,b]=g.dataset.go.split(':').map(Number);go(a,b);return}
