$('tostudy').onclick=()=>{try{speechSynthesis.cancel()}catch(e){}renderStudy('w')};$('sback').onclick=()=>go(si,cur);$('slib').onclick=renderLib;$('tabw').onclick=()=>renderStudy('w');$('tabq').onclick=()=>renderStudy('q');
