let glossDown=0;
document.addEventListener('mousedown',e=>{if(!(e.ctrlKey||e.metaKey||e.altKey))return;const t=e.target.closest('.w,[data-say]');if(!t)return;e.preventDefault();glossDown=Date.now();const k=t.dataset.k||t.dataset.say;light(k);showGloss(t,k)},true);
// Mac: Ctrl-click arrives as a right-click (contextmenu), not a click
document.addEventListener('contextmenu',e=>{if(!e.ctrlKey)return;const t=e.target.closest('.w,[data-say]');if(!t)return;e.preventDefault();if(Date.now()-glossDown>800){const k=t.dataset.k||t.dataset.say;light(k);showGloss(t,k)}});
$('langlist').addEventListener('keydown',e=>{const it=[...$('langlist').children],i=it.indexOf(document.activeElement);
  if(e.key==='ArrowDown'){e.preventDefault();(it[i+1]||it[0]).focus()}else if(e.key==='ArrowUp'){e.preventDefault();(it[i-1]||it[it.length-1]).focus()}
  else if(e.key==='Enter'||e.key===' '){e.preventDefault();if(it[i])setLang(it[i].dataset.lang)}else if(e.key==='Escape'){closeLang();$('langbtn').focus()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('.gloss').forEach(x=>x.remove());if(view!=='read')return;if(e.key==='ArrowRight')go(si,cur+1);if(e.key==='ArrowLeft')go(si,cur-1);if(!e.ctrlKey&&!e.metaKey&&!e.altKey&&!e.repeat&&!$('say').hidden){const a=document.activeElement,onBtn=a&&/^(BUTTON|INPUT|TEXTAREA|SELECT|A|SUMMARY)$/.test(a.tagName);if(e.key==='l'||e.key==='L'||(e.key===' '&&!onBtn)){e.preventDefault();toggleRead()}if(e.key==='s'||e.key==='S'){e.preventDefault();toggleSlow()}}});
$('howbtn').addEventListener('click',()=>{const d=$('howbox');d.open=true;d.scrollIntoView({behavior:'smooth',block:'start'})});
new MutationObserver(()=>{$('saylbl').textContent=$('say').classList.contains('reading')?T().stop:T().say}).observe($('say'),{attributes:true,attributeFilter:['class']});
applyLang();renderLib();
